package io.github.jackotom.hongguo.android;

import java.util.*;

/** Actual production Activity cache methods, deterministic lifecycle races, no devices or network. */
public final class PlayerCastCacheGuardsTest {
    static int passed, failed, checks;
    interface Checked {void run() throws Exception;}
    static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    static void group(String name,Checked action){try{action.run();passed++;System.out.println("PASS "+name);}catch(Throwable failure){failed++;System.out.println("FAIL "+name+": "+failure.getMessage());}}
    static PlayerCastCacheGuardsHarness fresh()throws Exception{return new PlayerCastCacheGuardsHarness();}
    static void cache(PlayerCastCacheGuardsHarness h,org.json.JSONObject target,String url,String quality){h.cacheEpisode(h.owner(target).optString("seriesId"),target,new PlaybackSources.Plan(url,PlayerCastCacheGuardsHarness.stageCeiling(quality,h.automaticCeiling)),quality,h.generation);}
    static void current(PlayerCastCacheGuardsHarness h){cache(h,h.queue.get(h.current),"https://fixture.invalid/current.mp4",h.actualQuality);}
    public static void main(String[]args)throws Exception{
        group("active cast blocks local prune",()->{PlayerCastCacheGuardsHarness h=fresh();h.castWasActive=true;h.pruneCache();check(h.cacheWorker.pending.isEmpty(),"cast local cleanup is never queued");h.pump();check(h.cache.prunes.isEmpty(),"cast window is not reduced to local one-episode window");});
        group("queued prune rechecks cast ownership",()->{PlayerCastCacheGuardsHarness h=fresh();h.pruneCache();check(h.cacheWorker.pending.size()==1,"local prune queued before cast");h.castWasActive=true;h.pump();check(h.cache.prunes.isEmpty(),"stale local cleanup does not delete prefetched cast episodes");});
        group("active cast blocks local cache enqueue",()->{PlayerCastCacheGuardsHarness h=fresh();h.castWasActive=true;current(h);check(h.cacheWorker.pending.isEmpty()&&h.caching.isEmpty(),"new local download is not queued while service owns playback");});
        group("queued cache yields to newly active cast",()->{PlayerCastCacheGuardsHarness h=fresh();current(h);h.castWasActive=true;h.pump();check(h.cache.fetches.isEmpty(),"old local task never starts downloading after cast handoff");check(h.cache.prunes.isEmpty()&&h.caching.isEmpty(),"skipped local task clears marker without pruning cast window");});
        group("old generation cache cannot start after selection",()->{PlayerCastCacheGuardsHarness h=fresh();current(h);h.generation++;h.current=4;h.pump();check(h.cache.fetches.isEmpty(),"stale selected-episode cache task does not start");check(h.caching.isEmpty(),"stale cache marker released");});
        group("download completing at cast handoff cannot prune future five",()->{PlayerCastCacheGuardsHarness h=fresh();h.cache.duringFetch=()->h.castWasActive=true;current(h);h.pump();check(h.cache.fetches.size()==1,"already running local transfer may complete");check(h.cache.prunes.isEmpty(),"completion cleanup respects current cast ownership");});
        group("normal local caching and rolling cleanup remain",()->{PlayerCastCacheGuardsHarness h=fresh();current(h);current(h);h.pump();check(h.cache.fetches.equals(Collections.singletonList("v1:720p")),"duplicate local cache stays single flight");check(h.cache.prunes.equals(Collections.singletonList("1:1"))&&h.caching.isEmpty(),"normal local rolling cleanup still runs");h.pruneCache();h.current=3;h.pump();check(h.cache.prunes.get(1).equals("4:1"),"prune reads current selection at execution time");});
        group("normal local next prefetch uses actual quality",()->{PlayerCastCacheGuardsHarness h=fresh();h.schedulePrefetch(h.generation);h.pump();check(PlaybackSources.calls.equals(Collections.singletonList("v2:720p")),"local next resolve uses actual 720p");check(h.cache.fetches.equals(Collections.singletonList("v2:720p"))&&h.caching.isEmpty(),"local next file still downloads");});
        group("active cast blocks local prefetch enqueue",()->{PlayerCastCacheGuardsHarness h=fresh();h.castWasActive=true;h.schedulePrefetch(h.generation);check(h.cacheWorker.pending.isEmpty()&&h.caching.isEmpty(),"service is sole prefetch coordinator during cast");});
        group("queued local prefetch yields before resolving",()->{PlayerCastCacheGuardsHarness h=fresh();h.schedulePrefetch(h.generation);h.castWasActive=true;h.pump();check(PlaybackSources.calls.isEmpty()&&h.cache.fetches.isEmpty()&&h.caching.isEmpty(),"old local resolver is suppressed after cast handoff");});
        group("cast begins during local source lookup",()->{PlayerCastCacheGuardsHarness h=fresh();PlaybackSources.duringResolve=()->h.castWasActive=true;h.schedulePrefetch(h.generation);h.pump();check(PlaybackSources.calls.size()==1&&h.cache.fetches.isEmpty(),"resolved local URL is not enqueued once casting takes ownership");check(h.caching.isEmpty(),"lookup marker released after late completion");});
        group("autoplay off and changed generation suppress queued lookup",()->{PlayerCastCacheGuardsHarness h=fresh();h.schedulePrefetch(h.generation);h.autoplay=false;h.pump();check(PlaybackSources.calls.isEmpty(),"disabled autoplay does not resolve queued local next");h.autoplay=true;h.schedulePrefetch(h.generation);h.generation++;h.pump();check(PlaybackSources.calls.isEmpty()&&h.caching.isEmpty(),"new selection ignores old local next lookup");});
        group("destroy and worker rejection release pending markers",()->{PlayerCastCacheGuardsHarness h=fresh();current(h);h.destroyed=true;h.pump();check(h.cache.fetches.isEmpty()&&h.cache.prunes.isEmpty()&&h.caching.isEmpty(),"destroyed Activity publishes no cache work");h=fresh();h.cacheWorker.reject=true;current(h);h.schedulePrefetch(h.generation);h.pruneCache();check(h.caching.isEmpty(),"executor rejection leaves no marker");});
        group("optional cache failures never change playback",()->{PlayerCastCacheGuardsHarness h=fresh();PlaybackSources.fail=true;h.schedulePrefetch(h.generation);h.pump();check(h.cache.fetches.isEmpty()&&h.caching.isEmpty()&&h.current==0,"background lookup failure leaves episode unchanged");h=fresh();h.current=h.queue.size()-1;h.schedulePrefetch(h.generation);h.pump();check(PlaybackSources.calls.isEmpty(),"last episode starts no further lookup");});
        group("manual downloads cleanup switch and hits retain original semantics",()->{PlayerCastCacheGuardsHarness h=fresh();h.offline=true;h.pruneCache();h.offline=false;h.cleanup=false;h.pruneCache();h.pump();check(h.cache.prunes.isEmpty(),"manual mode and disabled cleanup leave files alone");h.cache.hits.add("v2:720p");h.schedulePrefetch(h.generation);h.pump();check(PlaybackSources.calls.isEmpty()&&h.cache.fetches.isEmpty(),"matching cached next episode is not downloaded twice");});
        group("cross-season prefetch and cache tasks keep exact owner",()->{
            PlayerCastCacheGuardsHarness h=fresh();
            org.json.JSONObject first=new org.json.JSONObject().put("seriesId","111111").put("title","第一季"),second=new org.json.JSONObject().put("seriesId","222222").put("title","第二季");
            org.json.JSONObject before=new org.json.JSONObject().put("vid","1001").put("index",1).put("_series",first),following=new org.json.JSONObject().put("vid","1001").put("index",1).put("_series",second);
            h.queue.clear();h.queue.add(before);h.queue.add(following);h.series=first;h.queueSeries=first;
            h.schedulePrefetch(h.generation);h.pump();
            check(PlaybackSources.owners.equals(Collections.singletonList("222222:1001:720p")),"boundary prefetch resolves real next-season sid");
            check(h.cache.ownerFetches.equals(Collections.singletonList("222222:1001:1:720p")),"boundary prefetch stores next season's true local index");
            h.cache.ownerFetches.clear();cache(h,before,"https://fixture.invalid/a.mp4","720p");cache(h,following,"https://fixture.invalid/b.mp4","720p");h.series=second;h.pump();
            check(h.cache.ownerFetches.equals(Arrays.asList("111111:1001:1:720p","222222:1001:1:720p")),"same vid/local index cannot collide and queued task ignores mutable current series");
            check(h.caching.isEmpty(),"both season markers are released");
        });
        group("bounded local prefetch keeps exact source and cache ceiling",()->{PlayerCastCacheGuardsHarness h=fresh();h.actualQuality="480p";h.automaticCeiling=539;h.cache.hits.add("v2:480p");h.schedulePrefetch(h.generation);h.pump();check(PlaybackSources.calls.equals(Collections.singletonList("v2:480p")),"unbounded legacy file is not a bound539 cache hit");check(h.cache.lookupCeilings.equals(Collections.singletonList(539))&&h.cache.transferCeilings.equals(Collections.singletonList(539)),"lookup and actual Plan transfer share exact cap539");check(h.cache.capturedPlans.get(0).playbackCeiling==539&&h.caching.isEmpty(),"captured immutable bound plan is retained without marker leak");});
        group("same-generation ceiling changes discard old local lookup",()->{PlayerCastCacheGuardsHarness h=fresh();h.actualQuality="480p";h.automaticCeiling=575;PlaybackSources.duringResolve=()->h.automaticCeiling=539;h.schedulePrefetch(h.generation);h.pump();check(PlaybackSources.calls.size()==1&&h.cache.fetches.isEmpty(),"resolved plan cannot publish after a changed ceiling even within same generation");check(h.caching.isEmpty(),"old cap-specific lookup marker released");});
        System.out.println("PLAYER_CAST_CACHE_GUARDS_"+(failed==0?"OK":"FAILED")+" groupsPassed="+passed+" groupsFailed="+failed+" checks="+checks+" actualActivityMethods=true networkRequests=0 deviceTests=not_run");
        if(failed>0)System.exit(1);
    }
}
